steps.run:
echo "Checking if the langfuse server is up..."
retry_count=0
max_retries=20
until curl --output /dev/null --silent --head --fail http://localhost:3000/api/public/health && \
  node - <<'NODE'
const auth = Buffer.from(
  `${process.env.LANGFUSE_PUBLIC_KEY}:${process.env.LANGFUSE_SECRET_KEY}`,
).toString("base64");

fetch(`${process.env.LANGFUSE_BASE_URL}/api/public/projects`, {
  headers: {
    Authorization: `Basic ${auth}`,
  },
})
  .then(async (response) => {
    if (!response.ok) {
      throw new Error(`Request failed with status ${response.status}`);
    }

    return response.json();
  })
  .then((body) => {
    const project = body.data?.find(
      (candidate) =>
        candidate.id === process.env.LANGFUSE_INIT_PROJECT_ID,
    );

    if (!project) {
      throw new Error(
        `Expected initialized project ${process.env.LANGFUSE_INIT_PROJECT_ID}`,
      );
    }

    console.log(project.id);
  })
  .catch((error) => {
    console.error(error);
    process.exit(1);
  });
NODE
do
  retry_count=`expr $retry_count + 1`
  echo "Attempt $retry_count of $max_retries..."
  if [ $retry_count -ge $max_retries ]; then
    echo "Langfuse server did not respond in time. Printing logs..."
    (cd ./langfuse-server && docker compose ps)
    (cd ./langfuse-server && docker compose logs langfuse-web langfuse-worker)
    echo "Failing the step..."
    exit 1
  fi
  sleep 5
done
echo "Langfuse server is up and running!"

git diff --exit-code pnpm-lock.yaml || {
  echo "❌ Error: pnpm-lock.yaml was modified during install"
  exit 1
}

with.script:
const { owner, repo } = context.repo, event = context.payload;
const sha = event.merge_group?.head_sha ?? event.pull_request?.head.sha ?? event.sha;
const publish = (state, description) => github.rest.repos.createCommitStatus({ owner, repo, sha, context: "CLA gate", state, description });
if (context.eventName === "merge_group") return publish("success", "CLA enforcement handled on the pull request.");
if (event.branches?.some(b => b.name.startsWith("gh-readonly-queue/"))) return;
const prs = event.pull_request ? [event.pull_request] : await github.paginate(github.rest.pulls.list, { owner, repo, state: "open", per_page: 100 });
const current = prs.filter(pr => pr.state === "open" && pr.head.sha === sha);
if (current.length === 0) return;
await publish("failure", "CLA verification incomplete. Edit PR title/body to retry.");
/** Fork author attribution does not prove who can push to the branch. */
let exempt = current.every(pr => pr.head.repo?.full_name === `${owner}/${repo}`);
const checked = new Set([49699333, 41898282, 206951365, 199161495]); // Dependabot, Actions, Cursor.
for (const pr of current) {
  if (!exempt) break;
  const { repository: { pullRequest: live } } = await github.graphql(`
    query($owner: String!, $repo: String!, $number: Int!) { repository(owner: $owner, name: $repo) { pullRequest(number: $number) {
      headRefOid commits(first: 100) { totalCount nodes { commit { authors(first: 100) { totalCount nodes { user { login databaseId } } } } } }
    } } }`, { owner, repo, number: pr.number });
  if (live.headRefOid !== sha) return;
  exempt &&= live.commits.totalCount === live.commits.nodes.length && live.commits.nodes.every(({ commit: c }) => c.authors.totalCount > 0 && c.authors.totalCount === c.authors.nodes.length);
  for (const user of [pr.user, ...live.commits.nodes.flatMap(({ commit: c }) => c.authors.nodes.map(a => a.user))]) {
    if (!exempt) break;
    if (checked.has(user?.databaseId ?? user?.id)) continue;
    const permission = user ? await github.rest.repos.getCollaboratorPermissionLevel({ owner, repo, username: user.login }).then(r => r.data.permission).catch(e => { if (e.status === 404) return "none"; throw e; }) : "none";
    exempt &&= ["write", "maintain", "admin"].includes(permission);
    checked.add(user?.databaseId ?? user?.id);
  }
}
if (exempt) return publish("success", "All contributors exempt.");
const statuses = await github.paginate(github.rest.repos.listCommitStatusesForRef, { owner, repo, ref: sha });
const signed = statuses.find(s => s.context === "license/cla" && s.creator?.id === 2834609)?.state === "success"; // CLA Assistant's OAuth publisher.
if (signed) return publish("success", "CLA verified.");
return publish("failure", "CLA missing or unavailable. Sign, then edit PR title/body to retry.");

const owner = context.repo.owner;
const repo = context.repo.repo;
const issue_number = context.payload.pull_request.number;
const username = context.payload.pull_request.user.login;

let permission = "none";
try {
  const { data } = await github.rest.repos.getCollaboratorPermissionLevel({
    owner,
    repo,
    username,
  });
  permission = data.permission;
} catch (error) {
  if (error.status !== 404) {
    throw error;
  }
}

const canWrite = ["write", "admin"].includes(permission);
const comments = await github.paginate(github.rest.issues.listComments, {
  owner,
  repo,
  issue_number,
  per_page: 100,
});
const hasReviewRequest = comments.some(
  (comment) => comment.body?.trim() === "@claude review",
);

core.info(
  `PR #${issue_number} by ${username}: permission=${permission}, hasReviewRequest=${hasReviewRequest}`,
);

core.setOutput("should_comment", canWrite && !hasReviewRequest ? "true" : "false");

await github.rest.issues.createComment({
  owner: context.repo.owner,
  repo: context.repo.repo,
  issue_number: context.payload.pull_request.number,
  body: "@claude review",
});

